package main

import (
	_ "embed"
	"encoding/json"

	"github.com/egoist/mygo/ui"
)

// Generated by scripts/sync-radix.mjs from @radix-ui/colors, checked in CI.
//
//go:embed radix-native.json
var radixData []byte

var radixScales = func() map[string][2][12]string {
	var scales map[string][2][12]string
	if err := json.Unmarshal(radixData, &scales); err != nil {
		panic(err)
	}
	return scales
}()

func radixColor(name string, step int, dark bool) ui.Color {
	mode := 0
	if dark {
		mode = 1
	}
	return ui.Hex(radixScales[name][mode][step-1])
}

func paletteScales(palette string) (string, string) {
	switch palette {
	case "graphite":
		return "gray", "gray"
	case "forest":
		return "sage", "jade"
	case "sand":
		return "sand", "bronze"
	default:
		return "slate", "blue"
	}
}

func workbenchTheme(palette string, dark bool) *ui.Theme {
	neutral, accent := paletteScales(palette)
	n := func(step int) ui.Color { return radixColor(neutral, step, dark) }
	a := func(step int) ui.Color { return radixColor(accent, step, dark) }
	solid, hover := a(11), a(12)
	onAccent := radixColor("gray", 1, false)
	if dark {
		solid, hover, onAccent = a(9), a(10), radixColor("slate", 1, true)
	}
	if palette == "graphite" {
		solid, hover = a(12), a(11)
	}
	return &ui.Theme{
		Dark: dark, Background: n(1), Surface: n(3), SurfaceHover: n(4), SurfacePressed: n(5),
		Border: n(7), Text: n(12), TextMuted: n(11), Accent: solid, AccentHover: hover,
		AccentPressed: a(12), AccentText: onAccent, Danger: radixColor("red", 11, dark),
		Warning: radixColor("amber", 11, dark), Success: radixColor("jade", 11, dark),
		Selection: a(4), Focus: a(8), Scrollbar: n(8), Radius: 4, Spacing: 3, FontSize: 12,
	}
}
